CREATE TABLE t1 AS WITH RECURSIVE q(a)AS(VALUES(0)UNION ALL SELECT a+1 FROM q WHERE a<95)SELECT a,a+100 b,a+200 c,a+300 d FROM q;CREATE TABLE t2 AS SELECT b,a x FROM t1 WHERE a%2=0;CREATE INDEX i2 ON t2(b);CREATE TABLE t3 AS SELECT c,a y FROM t1 WHERE a%3=0;CREATE INDEX i3 ON t3(c);CREATE TABLE t4 AS SELECT d,a z FROM t1 WHERE a%5=0;CREATE INDEX i4 ON t4(d);ANALYZE;